(async()=>{
  const raw = localStorage.getItem('xray:fencing-job:v2') || localStorage.getItem('xray:fencing-job:v1');
  const id = raw ? (JSON.parse(raw).id || null) : null;
  if(!id) return 'NO_PROJECT_ID';
  const db = await new Promise((res,rej)=>{const r=indexedDB.open('xray-assistant-context-v1',1);
    r.onupgradeneeded=()=>{const d=r.result;
      if(!d.objectStoreNames.contains('entries')) d.createObjectStore('entries',{keyPath:'id'}).createIndex('jobId','jobId',{unique:false});
      if(!d.objectStoreNames.contains('profile')) d.createObjectStore('profile',{keyPath:'jobId'});};
    r.onsuccess=()=>res(r.result); r.onerror=()=>rej(r.error);});
  await new Promise((res,rej)=>{const tx=db.transaction(['entries','profile'],'readwrite');
    tx.objectStore('profile').put({jobId:id,updatedAt:'2026-09-10T04:00:00.000+10:00',
      notes:['role: fencing contractor in Queensland','units: millimetres on every drawing']});
    tx.objectStore('entries').put({id:id+'-seed-1',jobId:id,at:'2026-09-10T04:00:00.000+10:00',
      topic:'Northern boundary fence',
      summary:'Traced the northern boundary and confirmed the 900 mm setback.',
      evidence:'tool-receipt',tools:['xray_read_architect_design']});
    tx.oncomplete=()=>res(); tx.onabort=()=>rej(tx.error);});
  db.close();
  return 'SEEDED:'+id;
})()

